   }).catch((error: unknown) => {
     const detail = error instanceof Error ? error.message : "network error";
     throw new AgentError(`OpenRouter request failed: ${detail}`, 502);
   });

   const payload = (await response.json().catch(() => null)) as OpenRouterResponse | null;

