   const content = payload?.choices?.[0]?.message?.content;
   if (!content) {
     const finish = payload?.choices?.[0]?.finish_reason ?? "unknown";
     throw new AgentError(
       `The language model returned no text (finish reason: ${finish}). Please retry.`,
